    what: 'movie=1 rail',
    effect: 'The shipped ch13-survey rail drives the same keys/verbs a player uses. Used only to reach the drawing state, exactly as capture world-final/survey-1 did.',
    label: 'scripted-input-journey'
  });
  say(`renderer=${session.renderer} headed=${session.headed}`);
  await waitReady(page, { timeoutMs: 120000 });

  const earn0 = Date.now();
